import{_ as e,c as t,o,a2 as r}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"Recipes & Common Patterns","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"Overview","sidebarGroupTitle":"Recipes"},"headers":[],"relativePath":"guide/recipes/overview.md","filePath":"guide/recipes/overview.md","lastUpdated":1777448799000}'),a={name:"guide/recipes/overview.md"},i=r('<h1 id="recipes-common-patterns" tabindex="-1">Recipes &amp; Common Patterns <a class="header-anchor" href="#recipes-common-patterns" aria-label="Permalink to &quot;Recipes &amp; Common Patterns&quot;">​</a></h1><p>End-to-end walkthroughs for the tasks developers do most often on Modularous. Each recipe is self-contained and cross-references the reference docs rather than duplicating them.</p><p>Unlike <a href="/guide/module-features/overview">Module Features</a> (which describe <strong>what</strong> a trait does) or <a href="/guide/generics/overview">Generics</a> (which describe <strong>how</strong> a helper works), recipes describe <strong>how to accomplish a goal</strong> — the sequence of commands, files, and config changes from zero to working.</p><h2 id="available-recipes" tabindex="-1">Available Recipes <a class="header-anchor" href="#available-recipes" aria-label="Permalink to &quot;Available Recipes&quot;">​</a></h2><table><thead><tr><th>Recipe</th><th>Goal</th><th>Key concepts</th></tr></thead><tbody><tr><td><a href="./crud-module">CRUD Module</a></td><td>Ship a complete CRUD module with list, create, edit, delete</td><td><code>make:module</code>, Repository, Hydrate</td></tr><tr><td><a href="./file-uploads">File Uploads</a></td><td>Let users upload and retrieve files (avatar, attachments)</td><td><code>HasFileponds</code>, <code>input-filepond</code>, Media Library</td></tr><tr><td><a href="./state-machine">State Machine Workflow</a></td><td>Model records that move through named states with history</td><td><code>HasStateable</code>, <code>Processable</code>, State events</td></tr><tr><td><a href="./custom-input">Custom Form Input</a></td><td>Add a new input type that plugs into the form schema</td><td>Hydrate, <code>registerInputType</code>, Vue input component</td></tr></tbody></table><h2 id="when-to-read-a-recipe-vs-reference" tabindex="-1">When to Read a Recipe vs Reference <a class="header-anchor" href="#when-to-read-a-recipe-vs-reference" aria-label="Permalink to &quot;When to Read a Recipe vs Reference&quot;">​</a></h2><ul><li><strong>Recipe</strong> — you know what you want to <em>build</em> but not the exact sequence of steps.</li><li><strong>Reference</strong> — you already know the pattern and need method signatures, options, or edge cases.</li></ul><h2 id="recipe-structure" tabindex="-1">Recipe Structure <a class="header-anchor" href="#recipe-structure" aria-label="Permalink to &quot;Recipe Structure&quot;">​</a></h2><p>Every recipe follows the same outline so you can skim:</p><ol><li><strong>Goal</strong> — what you&#39;ll have at the end</li><li><strong>Prerequisites</strong> — assumed knowledge / required setup</li><li><strong>Steps</strong> — numbered, copy-pasteable</li><li><strong>Verification</strong> — how to confirm it works</li><li><strong>Next steps</strong> — where to go for customisation</li></ol><h2 id="contributing-a-recipe" tabindex="-1">Contributing a Recipe <a class="header-anchor" href="#contributing-a-recipe" aria-label="Permalink to &quot;Contributing a Recipe&quot;">​</a></h2><p>Recipes are most useful when they come from real tasks. If you solve a non-trivial problem with Modularous that required stitching several docs together, consider contributing it here. Keep it:</p><ul><li><strong>Goal-oriented</strong> — titled with the outcome, not the mechanism</li><li><strong>Minimal</strong> — the shortest path that actually works</li><li><strong>Cross-referenced</strong> — link to the reference docs instead of explaining what they already cover</li></ul>',13),s=[i];function n(d,c,l,h,p,u){return o(),t("div",null,s)}const f=e(a,[["render",n]]);export{g as __pageData,f as default};
